;; S5 oracle probes: LOADER surface (S5A2) — require/use/load.
;; Exit 0 (caught; chains printed).
(defn tx [label f]
  (println label "=>" (pr-str (try (f) (catch Throwable t
    (loop [t t acc []] (if t (recur (.getCause t) (conj acc (str (.getName (class t)) " | " (.getMessage t)))) acc)))))))
(tx "libs-initial" #(loaded-libs))
(tx "loaded-libs-shape" #(do [(type @#'clojure.core/*loaded-libs*) (sorted? (loaded-libs)) (= (loaded-libs) @@#'clojure.core/*loaded-libs*)]))
(tx "load-path-absent" #(do (nil? (resolve '*load-path*))))
(tx "req-set-ret" #(require 'clojure.set))
(tx "libs-after-set" #(loaded-libs))
(tx "req-set-again" #(do [(require 'clojure.set) (loaded-libs)]))
(tx "verbose-skip" #(with-out-str (require '[clojure.set :as set36] :verbose)))
(tx "alias-on-skip" #(do [(ns-name (get (ns-aliases *ns*) 'set36)) ((ns-resolve *ns* 'set36/union) #{1} #{2})]))
(tx "verbose-reload" #(with-out-str (require 'clojure.set :reload :verbose)))
(tx "req-test" #(do (require 'clojure.test) (loaded-libs)))
(tx "reload-keeps-tamper" #(do (alter-var-root #'clojure.template/apply-template (constantly :tampered36)) [(with-out-str (require 'clojure.test :reload :verbose)) (= :tampered36 @#'clojure.template/apply-template)]))
(tx "reload-all-keeps-tamper" #(do [(with-out-str (require 'clojure.test :reload-all :verbose)) (= :tampered36 @#'clojure.template/apply-template)]))
(tx "load-keeps-tamper" #(do (alter-var-root #'clojure.set/union (constantly :tampered36)) [(load "/clojure/set") (= :tampered36 @#'clojure.set/union)]))
(tx "req-check" #(do (require 'clojure.test.check) (into [] (filter (fn [s] (.startsWith (str s) "clojure.test.check")) (loaded-libs)))))
(tx "reload-check-restores" #(do (alter-var-root #'clojure.test.check/quick-check (constantly :tampered36)) [(with-out-str (require 'clojure.test.check :reload :verbose)) (fn? @#'clojure.test.check/quick-check)]))
(tx "reload-all-check" #(do (alter-var-root #'clojure.test.check/quick-check (constantly :tampered36)) [(with-out-str (require 'clojure.test.check :reload-all :verbose)) (fn? @#'clojure.test.check/quick-check)]))
(tx "req-missing" #(require 'no.such.lib36))
(tx "req-missing-clean" #(do (try (require 'no.such.lib36) (catch Throwable t)) [(find-ns 'no.such.lib36) (contains? (loaded-libs) 'no.such.lib36)]))
(tx "req-dash-map" #(require 'my-lib36.sub36))
(tx "req-underscore-note" #(require 'has_under.score36))
(tx "in-ns-fixture" #(do (in-ns 'mem36.a) (intern 'mem36.a 'v36 42) (in-ns 'user) [(some? (find-ns 'mem36.a)) (contains? (loaded-libs) 'mem36.a)]))
(tx "req-mem-fixture" #(require '[mem36.a :as m36]))
(tx "mem-survives" #(do (try (require 'mem36.a) (catch Throwable t)) [(some? (find-ns 'mem36.a)) @(ns-resolve 'mem36.a 'v36)]))
(tx "ns-marks-loaded" #(do (eval '(ns tmp36.a)) (in-ns 'user) [(contains? (loaded-libs) 'tmp36.a) (some? (find-ns 'tmp36.a))]))
(tx "req-ns-marked" #(do [(require '[tmp36.a :as t36]) (ns-name (get (ns-aliases *ns*) 't36))]))
(tx "req-stale" #(do (remove-ns 'tmp36.a) (require '[tmp36.a :as t36b])))
(tx "req-mismatch-as" #(require '[clojure.core-deftype :as dt36]))
(tx "req-mismatch-plain" #(do (require 'clojure.core-deftype) [(contains? (loaded-libs) 'clojure.core-deftype) (find-ns 'clojure.core-deftype)]))
(tx "req-mismatch-stale" #(require '[clojure.core-deftype :as dt36b]))
(tx "req-prefix" #(do (create-ns 'probe36.f) (binding [*ns* (the-ns 'probe36.f)] [(require '(clojure [walk :as w36])) (ns-name (get (ns-aliases *ns*) 'w36))])))
(tx "req-as-refer" #(do (create-ns 'probe36.h) (binding [*ns* (the-ns 'probe36.h)] (require '[clojure.string :as s36b :refer [join]]) [(ns-name (get (ns-aliases *ns*) 's36b)) (str (get (ns-refers *ns*) 'join)) ((deref (get (ns-refers *ns*) 'join)) "," [1 2])])))
(tx "req-refer-all" #(do (create-ns 'probe36.g) (binding [*ns* (the-ns 'probe36.g)] (require '[clojure.set :refer :all]) [(contains? (ns-refers *ns*) 'union) (count (ns-refers *ns*))])))
(tx "use-only" #(do (create-ns 'probe36.c) (binding [*ns* (the-ns 'probe36.c)] [(use '[clojure.string :only [join]]) (contains? (ns-refers *ns*) 'join) (contains? (ns-refers *ns*) 'split) (count (ns-refers *ns*))])))
(tx "use-exclude" #(do (create-ns 'probe36.d) (binding [*ns* (the-ns 'probe36.d)] (use '[clojure.string :exclude [join]]) [(contains? (ns-refers *ns*) 'join) (contains? (ns-refers *ns*) 'split) (count (ns-refers *ns*))])))
(tx "use-rename" #(do (create-ns 'probe36.e) (binding [*ns* (the-ns 'probe36.e)] (use '[clojure.string :rename {join j36}]) [(str (ns-resolve 'probe36.e 'j36)) (contains? (ns-refers *ns*) 'join) (contains? (ns-refers *ns*) 'split)])))
(tx "load-abs" #(do [(with-out-str (try (push-thread-bindings {#'clojure.core/*loading-verbosely* true}) (load "/clojure/walk") (finally (pop-thread-bindings)))) (contains? (loaded-libs) 'clojure.walk) (some? (find-ns 'clojure.walk))]))
(tx "load-no-nsform" #(let [before (loaded-libs)] [(load "/clojure/core_print") (= before (loaded-libs))]))
(tx "load-rel-user" #(load "x-nofile-36"))
(tx "load-rel-nested" #(do (create-ns 'aa36.bb) (binding [*ns* (the-ns 'aa36.bb)] (load "y-nofile-36"))))
(tx "req-empty" #(require))
(tx "req-unsupported" #(require 'clojure.set :bogus))
(tx "use-bare" #(do (create-ns 'probe36.i) (binding [*ns* (the-ns 'probe36.i)] [(use 'clojure.set) (contains? (ns-refers *ns*) 'union) (count (ns-refers *ns*))])))
(tx "load-ext" #(load "x-nofile-36.clj"))
(tx "req-string" #(require "clojure.string"))
(tx "file-toplevel" #(str *file*))
(tx "file-loadstring" #(do (load-string "(def p36s-file *file*)") (pr-str @(ns-resolve 'user 'p36s-file))))
(tx "file-loadfile" #(do (load-file "docs/t1174/probes/p36file.clj") (str @(ns-resolve 'user 'p36f-file))))
(tx "req-as-string" #(require '[clojure.string :as "s36c"]))
(tx "req-refer-scalar" #(require '[clojure.string :refer join]))
(tx "req-opts-bare" #(require 'clojure.string :as))
(tx "use-with-as" #(do (create-ns 'probe36.k) (binding [*ns* (the-ns 'probe36.k)] [(use '[clojure.string :as s36d :only [join]]) (contains? (ns-refers *ns*) 'join) (contains? (ns-aliases *ns*) 's36d)])))
(tx "refer-missing-lib" #(refer 'no.such.lib36x))
(tx "refer-missing-var" #(do (create-ns 'probe36.j) (binding [*ns* (the-ns 'probe36.j)] [(refer 'clojure.string :only '[no-such-var36]) (contains? (ns-refers *ns*) 'no-such-var36)])))
(tx "file-dotdot" #(do (load-file "docs/t1174/probes/../probes/p36file.clj") (str @(ns-resolve 'user 'p36f-file))))
(tx "ns-resolve-alias" #(do (require 'clojure.string) (try (do (alias 's36e 'clojure.string) (str (ns-resolve *ns* 's36e/join))) (finally (ns-unalias *ns* 's36e)))))
(tx "refer-private" #(do (create-ns 'probe36.m) (intern 'probe36.m 'pub36 1) (alter-meta! (intern 'probe36.m 'priv36 2) assoc :private true) (create-ns 'probe36.n) (binding [*ns* (the-ns 'probe36.n)] (refer 'probe36.m :only '[priv36]))))
(tx "refer-rename-scalar" #(do (create-ns 'probe36.o) (binding [*ns* (the-ns 'probe36.o)] (refer 'clojure.string :rename 'join))))
(tx "refer-exclude-scalar" #(do (create-ns 'probe36.p) (binding [*ns* (the-ns 'probe36.p)] [(refer 'clojure.string :exclude 'join) (count (ns-refers *ns*)) (contains? (ns-refers *ns*) 'join)])))
